OWNED_DESCENDANT_SOURCE = "def subreaper_flag():\n    value = ctypes.c_int()\n    if ctypes.CDLL(None, use_errno=True).prctl(37, ctypes.byref(value), 0, 0, 0) != 0 or value.value not in (0, 1):\n        raise ValueError('debugger_subreaper_unavailable')\n    return value.value\n\ndef children_of(pid):\n    try:\n        raw = pathlib.Path('/proc/' + str(pid) + '/task/' + str(pid) + '/children').read_text()\n    except FileNotFoundError:\n        if pid != os.getpid() and pid in owned_descendants and select.select([owned_descendants[pid]['pidfd']], [], [], 0)[0]:\n            return []\n        raise ValueError('debugger_descendant_identity_unknown')\n    fields = raw.split()\n    if len(fields) > 64 or any((not x.isdecimal() or int(x) <= 1 for x in fields)) or len(set(fields)) != len(fields):\n        raise ValueError('debugger_scope_limit')\n    return [int(x) for x in fields]\n\ndef ownership_admit():\n    global original_subreaper\n    if not hasattr(os, 'pidfd_open') or not hasattr(signal, 'pidfd_send_signal'):\n        raise ValueError('debugger_pidfd_unavailable')\n    if children_of(os.getpid()):\n        raise ValueError('debugger_initial_children')\n    original_subreaper = subreaper_flag()\n    if ctypes.CDLL(None, use_errno=True).prctl(36, 1, 0, 0, 0) != 0 or subreaper_flag() != 1:\n        raise ValueError('debugger_subreaper_unavailable')\n\ndef descendant_birth(pid):\n    raw = pathlib.Path('/proc/' + str(pid) + '/stat').read_text()\n    parts = raw.rsplit(')', 1)[1].split()\n    rows = {line.split(':', 1)[0]: line.split(':', 1)[1].split() for line in pathlib.Path('/proc/' + str(pid) + '/status').read_text().splitlines() if ':' in line}\n    if int(raw.split(' ', 1)[0]) != pid or rows['Uid'] != [str(identity_host['uid'])] * 4 or rows['Gid'] != [str(identity_host['gid'])] * 4 or (rows['Groups'] != [str(x) for x in identity_host['groups']]):\n        raise ValueError('debugger_descendant_identity_unknown')\n    if pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip() != EXPECTED_BOOT:\n        raise ValueError('host_boot_changed')\n    return {'pid': pid, 'parentPid': int(parts[1]), 'startTicks': int(parts[19]), 'bootId': EXPECTED_BOOT, 'uid': identity_host['uid'], 'gid': identity_host['gid'], 'groups': list(identity_host['groups'])}\n\ndef collect_descendants():\n    if subreaper_flag() != 1:\n        raise ValueError('debugger_subreaper_restore_unknown')\n    queue = [os.getpid()]\n    seen = set()\n    while queue:\n        parent = queue.pop()\n        for pid in children_of(parent):\n            if pid in seen:\n                raise ValueError('debugger_scope_limit')\n            seen.add(pid)\n            if len(seen) > 64:\n                raise ValueError('debugger_scope_limit')\n            if pid not in owned_descendants:\n                try:\n                    before = descendant_birth(pid)\n                    fd = os.pidfd_open(pid, 0)\n                except ProcessLookupError:\n                    continue\n                except OSError:\n                    raise ValueError('debugger_pidfd_unavailable')\n                try:\n                    after = descendant_birth(pid)\n                    if before != after or before['parentPid'] != parent:\n                        raise ValueError('debugger_descendant_identity_unknown')\n                    owned_descendants[pid] = {'identity': before, 'pidfd': fd, 'reaped': False}\n                    fd = None\n                finally:\n                    if fd is not None:\n                        os.close(fd)\n            else:\n                current = descendant_birth(pid)\n                original = owned_descendants[pid]['identity']\n                if any((current[k] != original[k] for k in ('pid', 'startTicks', 'bootId', 'uid', 'gid', 'groups'))):\n                    raise ValueError('debugger_descendant_identity_unknown')\n                if current['parentPid'] != parent:\n                    raise ValueError('debugger_descendant_identity_unknown')\n            queue.append(pid)\n    return len(seen)\n\ndef close_descendants():\n    global wait_status\n    deadline = min(time.monotonic() + 3, child_deadline - 2) if child_deadline is not None else time.monotonic() + 3\n    try:\n        while True:\n            collect_descendants()\n            for pid, record in list(owned_descendants.items()):\n                if not select.select([record['pidfd']], [], [], 0)[0]:\n                    signal.pidfd_send_signal(record['pidfd'], signal.SIGKILL, None, 0)\n            while True:\n                try:\n                    pid, status = os.waitpid(-1, os.WNOHANG)\n                except ChildProcessError:\n                    break\n                if not pid:\n                    break\n                if pid not in owned_descendants:\n                    raise ValueError('debugger_cleanup_unknown')\n                owned_descendants[pid]['reaped'] = True\n                if pid == process:\n                    wait_status = status\n            if not children_of(os.getpid()) and all((select.select([r['pidfd']], [], [], 0)[0] for r in owned_descendants.values())):\n                break\n            if time.monotonic() >= deadline:\n                raise ValueError('debugger_cleanup_unknown')\n            time.sleep(0.01)\n        return {'originalSubreaper': original_subreaper, 'restoredSubreaper': original_subreaper, 'allDescendantsExited': True, 'finalChildren': [], 'identities': [r['identity'] for r in owned_descendants.values()], 'reapedPids': [pid for pid, r in owned_descendants.items() if r['reaped']]}\n    finally:\n        restore_error = None\n        try:\n            if original_subreaper is not None:\n                if children_of(os.getpid()) or any((not select.select([r['pidfd']], [], [], 0)[0] for r in owned_descendants.values())):\n                    raise ValueError('debugger_cleanup_unknown')\n                if subreaper_flag() != 1 or ctypes.CDLL(None, use_errno=True).prctl(36, original_subreaper, 0, 0, 0) != 0 or subreaper_flag() != original_subreaper:\n                    raise ValueError('debugger_subreaper_restore_unknown')\n        except BaseException as error:\n            restore_error = error\n        finally:\n            for record in owned_descendants.values():\n                os.close(record['pidfd'])\n        if restore_error is not None:\n            raise restore_error\n\ndef cleanup_selftest():\n    global original_subreaper, owned_descendants, wait_status, process, child_deadline\n    intent = {'correlationId': CORRELATION, 'kind': 'own-harmless-separated-session-closure', 'maximumSeconds': 6, 'nativeGdbLaunched': False, 'replayAllowed': False}\n    write_record(result_fd, 'selftest-intent.json', json.dumps(intent, sort_keys=True).encode())\n    os.fsync(result_fd)\n    ownership_admit()\n    read, write = os.pipe()\n    child_deadline = time.monotonic() + 6\n    process = os.fork()\n    raw = b''\n    if process == 0:\n        try:\n            os.close(read)\n            os.setsid()\n            escape = os.fork()\n            if escape == 0:\n                os.setsid()\n                os.write(write, (str(os.getpid()) + '\\n').encode())\n                os.close(write)\n                time.sleep(10)\n                os._exit(0)\n            os.close(write)\n            time.sleep(10)\n            os._exit(0)\n        except BaseException:\n            try:\n                os.write(write, b'SELFTEST_UNKNOWN\\n')\n            except OSError:\n                pass\n            os._exit(125)\n    os.close(write)\n    try:\n        if not select.select([read], [], [], 2)[0]:\n            raise ValueError('debugger_selftest_unknown')\n        raw = os.read(read, 128)\n        if not raw.endswith(b'\\n') or not raw[:-1].isdigit():\n            raise ValueError('debugger_selftest_unknown')\n        escape = int(raw[:-1])\n        collect_descendants()\n        if len(owned_descendants) != 2 or set(owned_descendants) != {process, escape} or os.getpgid(process) != process or (os.getpgid(escape) != escape):\n            raise ValueError('debugger_selftest_unknown')\n        closure = close_descendants()\n        if set(closure['reapedPids']) != {process, escape} or children_of(os.getpid()) or subreaper_flag() != closure['originalSubreaper']:\n            raise ValueError('debugger_selftest_unknown')\n    finally:\n        os.close(read)\n    proof = {'state': 'selftest-own-descendant-closure-proven', 'intent': intent, 'closure': closure, 'rawBytes': len(raw), 'rawSha256': hashlib.sha256(raw).hexdigest(), 'nativeGdbLaunched': False, 'replayAllowed': False}\n    original_subreaper = None\n    owned_descendants = {}\n    wait_status = None\n    process = None\n    child_deadline = None\n    write_record(result_fd, 'selftest-stdout.private', raw)\n    write_record(result_fd, 'selftest-proof.json', json.dumps(proof, sort_keys=True).encode())\n    os.fsync(result_fd)\n    return proof\n\ndef write_record(parent, name, raw):\n    if len(raw) > 4096:\n        for number, offset in enumerate(range(0, len(raw), 4096)):\n            write_record(parent, name + '.part-' + str(number), raw[offset:offset + 4096])\n        write_record(parent, name + '.manifest.json', json.dumps({'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest(), 'partBytes': 4096, 'partCount': (len(raw) + 4095) // 4096}, sort_keys=True).encode())\n        return\n    fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 384, dir_fd=parent)\n    try:\n        view = memoryview(raw)\n        while view:\n            count = os.write(fd, view)\n            if count <= 0:\n                raise ValueError('record_write_unknown')\n            view = view[count:]\n        os.fsync(fd)\n    finally:\n        os.close(fd)\n"
